    <style>
        :root {
            --primary: #0A61F7;
            --secondary: #39FF14;
            --accent: #0A61F7;
            --border-glow: rgba(10, 97, 247, 0.5);
            --primary-rgb: 10, 97, 247;
            --bg: #000000;
            --surface: rgba(10, 10, 10, 0.7);
            --glass: rgba(255, 255, 255, 0.03);
            --glass-strong: rgba(255, 255, 255, 0.05);
            --border: rgba(255, 255, 255, 0.1);
            --text: #f0f0f0;
            --text-muted: #a0a0a0;
            --transition-color-slow: color 30s ease-in-out, background-color 30s ease-in-out, border-color 30s ease-in-out, text-shadow 30s ease-in-out;
        }

        html { scroll-behavior: smooth; font-size: 14px; }
        body {
            font-family: 'Inter', sans-serif;
            background-color: var(--bg);
            color: var(--text);
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
        }

        .aurora-background {
            position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
            pointer-events: none; z-index: -1; overflow: hidden;
        }
        .aurora {
            position: absolute; border-radius: 50%; mix-blend-mode: screen;
            filter: blur(120px); opacity: 0;
            background-color: var(--primary); /* Start color */
            transition: background-color 30s ease-in-out, opacity 8s ease-in-out;
            animation: pulse 35s ease-in-out infinite alternate;
        }
        .aurora.visible { opacity: 0.3; }
        .aurora.one {
            width: 80vmax; height: 80vmax; animation-name: move-one, pulse;
            animation-duration: 1200s, 35s; animation-timing-function: linear, ease-in-out;
            animation-iteration-count: infinite, infinite; animation-direction: alternate, alternate;
        }
        .aurora.two {
            width: 70vmax; height: 70vmax; animation-name: move-two, pulse;
            animation-duration: 1050s, 40s; animation-timing-function: linear, ease-in-out;
            animation-iteration-count: infinite, infinite; animation-direction: alternate, alternate;
        }

        @keyframes move-one { from { transform: translate(-20vw, -20vh) scale(1); } to { transform: translate(50vw, 80vh) scale(1.2); } }
        @keyframes move-two { from { transform: translate(80vw, 30vh) scale(1); } to { transform: translate(-10vw, 60vh) scale(1.3); } }
        @keyframes pulse { from { opacity: 0.2; } to { opacity: 0.4; } }

        .gradient-text, .dynamic-text-color {
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            transition: var(--transition-color-slow);
        }
        .dynamic-bg { transition: var(--transition-color-slow); }
        .dynamic-border { transition: var(--transition-color-slow); }

        ::-webkit-scrollbar { width: 5px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.1); border-radius: 3px; }
        ::-webkit-scrollbar-thumb:hover { background: rgba(255, 255, 255, 0.2); }

        .ai-content pre {
            background: rgba(0,0,0,0.4); border: 1px solid var(--border);
            border-radius: 0.5rem; padding: 0.75rem; margin: 0.75rem 0;
            font-size: 0.8rem; overflow-x: auto;
        }
        .ai-content code { font-family: 'SF Mono', 'Fira Code', 'Menlo', monospace; }

        .glass-bg {
            background-color: var(--surface); backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px);
        }

        /* Input Range Styles */
        input[type=range] { -webkit-appearance: none; appearance: none; width: 100%; background: transparent; }
        input[type=range]:focus { outline: none; }
        input[type=range]::-webkit-slider-runnable-track {
            width: 100%; height: 4px; cursor: pointer; background: var(--glass-strong);
            border-radius: 2px; border: 1px solid var(--border);
        }
        input[type=range]::-webkit-slider-thumb {
            -webkit-appearance: none; appearance: none;
            height: 14px; width: 14px; border-radius: 50%; background: var(--primary);
            cursor: pointer; margin-top: -6px; border: 1px solid var(--border);
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in {
            animation: fadeIn 0.5s ease-out;
        }

        /* Override Tailwind and add custom animations */
        .transition-all { transition: all 0.2s ease; }
        .transition-transform { transition: transform 0.3s ease; }
        .hover\:scale-110:hover { transform: scale(1.1); }
        .hover\:rotate-12:hover { transform: rotate(12deg); }

        .sidebar-content {
            padding: 20px;
            flex-grow: 1;
        }

        .fold-history {
            margin-bottom: 24px;
        }

        .section-title {
            font-size: 0.9rem;
            font-weight: 600;
            color: var(--accent);
            margin-bottom: 12px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .history-item {
            background: var(--glass);
            border: 1px solid var(--border);
            border-radius: var(--radius-sm);
            padding: 12px;
            margin-bottom: 8px;
            cursor: pointer;
            transition: all 0.2s var(--transition-curve);
        }

        .history-item:hover {
            background: var(--glass-strong);
            border-color: var(--primary);
            transform: translateX(4px);
        }

        .history-title {
            font-size: 0.85rem;
            font-weight: 600;
            margin-bottom: 4px;
        }

        .history-meta {
            font-size: 0.75rem;
            color: var(--text-muted);
            display: flex;
            justify-content: space-between;
        }

        /* Main Content */
        .main-content {
            flex: 1;
            margin-left: 0;
            display: flex;
            flex-direction: column;
            transition: margin-left 0.4s var(--transition-curve);
            min-height: 100vh;
        }

        .header {
            padding: 12px 20px;
            background: var(--surface);
            backdrop-filter: blur(60px) saturate(180%);
            border-bottom: 1px solid var(--border);
            display: flex;
            align-items: center;
            justify-content: space-between;
            position: sticky;
            top: 0;
            z-index: 100;
        }

        .header-title {
            font-size: 1.1rem;
            font-weight: 600;
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .menu-toggle {
            background: var(--glass-strong);
            border: 1px solid var(--border);
            border-radius: var(--radius-sm);
            padding: 8px;
            color: var(--text);
            cursor: pointer;
            transition: all 0.2s var(--transition-curve);
            font-size: 1rem;
            width: 40px;
            height: 40px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .menu-toggle:hover {
            background: var(--glass-strong);
            border-color: var(--primary);
            color: var(--primary);
        }

        /* Welcome Screen */
        .welcome-screen {
            text-align: center;
            max-width: 600px;
            margin: 0 auto;
            padding: 60px 20px;
            animation: fadeIn 1s var(--transition-curve);
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .welcome-title {
            font-size: 3rem;
            margin-bottom: 1rem;
            font-weight: 800;
            background: linear-gradient(135deg, var(--primary), var(--secondary), var(--accent));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            text-shadow: var(--glow);
        }

        .welcome-subtitle {
            font-size: 1.2rem;
            color: var(--text-muted);
            margin-bottom: 2rem;
            line-height: 1.6;
        }

        .start-folding-btn {
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            border: none;
            color: #000;
            border-radius: var(--radius-lg);
            padding: 16px 32px;
            font-weight: 600;
            font-size: 1.1rem;
            cursor: pointer;
            transition: all 0.3s var(--transition-curve);
            box-shadow: var(--glow);
        }

        .start-folding-btn:hover {
            transform: translateY(-3px);
            box-shadow: 0 0 40px var(--primary);
        }

        /* Folding Interface */
        .folding-interface {
            display: none;
            padding: 20px;
            max-width: 1200px;
            margin: 0 auto;
            width: 100%;
        }

        .folding-interface.active {
            display: block;
        }

        .input-section {
            background: var(--surface);
            border: 1px solid var(--border);
            border-radius: var(--radius-lg);
            padding: 24px;
            margin-bottom: 24px;
            backdrop-filter: blur(60px);
        }

        .input-title {
            font-size: 1.1rem;
            font-weight: 600;
            color: var(--primary);
            margin-bottom: 16px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .input-group {
            margin-bottom: 16px;
        }

        .input-label {
            display: block;
            font-size: 0.9rem;
            font-weight: 500;
            color: var(--text);
            margin-bottom: 6px;
        }

        .input-field {
            width: 100%;
            background: var(--glass);
            border: 1px solid var(--border);
            border-radius: var(--radius-md);
            padding: 12px 16px;
            color: var(--text);
            font-size: 0.9rem;
            transition: all 0.2s var(--transition-curve);
        }

        .input-field:focus {
            outline: none;
            border-color: var(--primary);
            box-shadow: 0 0 0 3px rgba(44, 255, 5, 0.1);
        }

        .sequence-textarea {
            min-height: 120px;
            font-family: 'Courier New', monospace;
            resize: vertical;
        }

        .sequence-info {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 8px;
            font-size: 0.8rem;
            color: var(--text-muted);
        }

        .predict-btn {
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            border: none;
            color: #000;
            border-radius: var(--radius-md);
            padding: 14px 28px;
            font-weight: 600;
            font-size: 1rem;
            cursor: pointer;
            transition: all 0.3s var(--transition-curve);
            box-shadow: var(--glow);
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .predict-btn:hover:not(:disabled) {
            transform: translateY(-2px);
            box-shadow: 0 0 30px var(--primary);
        }

        .predict-btn:disabled {
            opacity: 0.6;
            cursor: not-allowed;
        }

        /* Progress Section */
        .progress-section {
            background: var(--surface);
            border: 1px solid var(--border);
            border-radius: var(--radius-lg);
            padding: 24px;
            margin-bottom: 24px;
            backdrop-filter: blur(60px);
            display: none;
        }

        .progress-section.active {
            display: block;
            animation: slideIn 0.5s var(--transition-curve);
        }

        @keyframes slideIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .progress-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 20px;
        }

        .progress-title {
            font-size: 1.1rem;
            font-weight: 600;
            color: var(--primary);
        }

        .progress-status {
            font-size: 0.9rem;
            color: var(--text-muted);
        }

        .progress-bar {
            width: 100%;
            height: 8px;
            background: var(--glass);
            border-radius: 4px;
            overflow: hidden;
            margin-bottom: 16px;
        }

        .progress-fill {
            height: 100%;
            background: linear-gradient(90deg, var(--primary), var(--secondary));
            border-radius: 4px;
            transition: width 0.3s ease;
            box-shadow: 0 0 10px var(--primary);
        }

        .progress-info {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 16px;
        }

        .info-card {
            background: var(--glass);
            border: 1px solid var(--border);
            border-radius: var(--radius-md);
            padding: 16px;
        }

        .info-card-title {
            font-size: 0.8rem;
            color: var(--text-muted);
            margin-bottom: 4px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .info-card-value {
            font-size: 1.1rem;
            font-weight: 600;
            color: var(--accent);
        }

        /* 3D Viewer */
        .viewer-section {
            background: var(--surface);
            border: 1px solid var(--border);
            border-radius: var(--radius-lg);
            padding: 24px;
            backdrop-filter: blur(60px);
            display: none;
        }

        .viewer-section.active {
            display: block;
            animation: slideIn 0.5s var(--transition-curve);
        }

        .viewer-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 20px;
        }

        .viewer-title {
            font-size: 1.1rem;
            font-weight: 600;
            color: var(--primary);
        }

        .viewer-controls {
            display: flex;
            gap: 8px;
        }

        .control-btn {
            background: var(--glass);
            border: 1px solid var(--border);
            border-radius: var(--radius-sm);
            padding: 8px 12px;
            color: var(--text);
            cursor: pointer;
            transition: all 0.2s var(--transition-curve);
            font-size: 0.85rem;
        }

        .control-btn:hover {
            background: var(--glass-strong);
            border-color: var(--primary);
            color: var(--primary);
        }

        .protein-viewer {
            width: 100%;
            height: 500px;
            background: var(--glass);
            border: 1px solid var(--border);
            border-radius: var(--radius-md);
            position: relative;
            overflow: hidden;
        }

        /* Results Section */
        .results-section {
            background: var(--surface);
            border: 1px solid var(--border);
            border-radius: var(--radius-lg);
            padding: 24px;
            margin-top: 24px;
            backdrop-filter: blur(60px);
            display: none;
        }

        .results-section.active {
            display: block;
            animation: slideIn 0.5s var(--transition-curve);
        }

        .results-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 20px;
        }

        .results-title {
            font-size: 1.1rem;
            font-weight: 600;
            color: var(--primary);
        }

        .download-btn {
            background: linear-gradient(135deg, var(--accent), var(--special));
            border: none;
            color: #000;
            border-radius: var(--radius-md);
            padding: 10px 20px;
            font-weight: 600;
            font-size: 0.9rem;
            cursor: pointer;
            transition: all 0.3s var(--transition-curve);
            box-shadow: 0 0 15px var(--accent);
        }

        .download-btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 0 25px var(--accent);
        }

        .confidence-chart {
            width: 100%;
            height: 300px;
            background: var(--glass);
            border: 1px solid var(--border);
            border-radius: var(--radius-md);
            margin-bottom: 20px;
        }

        .stats-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 16px;
            margin-top: 20px;
        }

        .stat-card {
            background: var(--glass);
            border: 1px solid var(--border);
            border-radius: var(--radius-md);
            padding: 16px;
        }

        .stat-title {
            font-size: 0.8rem;
            color: var(--text-muted);
            margin-bottom: 4px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .stat-value {
            font-size: 1.1rem;
            font-weight: 600;
            color: var(--highlight);
        }

        /* Responsive Design */
        @media (max-width: 768px) {
            .sidebar {
                width: 280px;
            }

            .welcome-title {
                font-size: 2.2rem;
            }

            .folding-interface {
                padding: 16px;
            }

            .progress-info {
                grid-template-columns: 1fr;
            }

            .protein-viewer {
                height: 400px;
            }
        }

        /* Loading Animation */
        .loading-dots {
            display: inline-flex;
            gap: 4px;
        }

        .loading-dot {
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: var(--primary);
            animation: loadingPulse 1.4s ease-in-out infinite both;
        }

        .loading-dot:nth-child(1) { animation-delay: -0.32s; }
        .loading-dot:nth-child(2) { animation-delay: -0.16s; }

        @keyframes loadingPulse {
            0%, 80%, 100% { transform: scale(0.8); opacity: 0.5; }
            40% { transform: scale(1); opacity: 1; }
        }

        /* Error states */
        .error-message {
            background: rgba(255, 20, 147, 0.1);
            border: 1px solid var(--accent);
            border-radius: var(--radius-md);
            padding: 12px 16px;
            color: var(--accent);
            font-size: 0.9rem;
            margin-top: 8px;
            display: none;
        }

        .error-message.show {
            display: block;
            animation: errorSlide 0.3s ease;
        }

        @keyframes errorSlide {
            from { opacity: 0; transform: translateY(-10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* Success states */
        .success-message {
            background: rgba(44, 255, 5, 0.1);
            border: 1px solid var(--primary);
            border-radius: var(--radius-md);
            padding: 12px 16px;
            color: var(--primary);
            font-size: 0.9rem;
            margin-top: 8px;
            display: none;
        }

        .success-message.show {
            display: block;
            animation: successSlide 0.3s ease;
        }

        @keyframes successSlide {
            from { opacity: 0; transform: translateY(-10px); }
            to { opacity: 1; transform: translateY(0); }
        }
    </style>
</head>
