            font-weight: 500;
            color: var(--text);
            margin-bottom: 6px;
        }

        .input-field {
            width: 100%;
            background: var(--glass);
            border: 1px solid var(--border);
            border-radius: var(--radius-md);
            padding: 12px 16px;
            color: var(--text);
            font-size: 0.9rem;
            transition: all 0.2s var(--transition-curve);
        }

        .input-field:focus {
            outline: none;
            border-color: var(--primary);
            box-shadow: 0 0 0 3px rgba(44, 255, 5, 0.1);
        }

        .sequence-textarea {
            min-height: 120px;
            font-family: 'Courier New', monospace;
            resize: vertical;
        }

        .sequence-info {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 8px;
            font-size: 0.8rem;
            color: var(--text-muted);
        }

        .predict-btn {
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            border: none;
            color: #000;
            border-radius: var(--radius-md);
            padding: 14px 28px;
            font-weight: 600;
            font-size: 1rem;
            cursor: pointer;
            transition: all 0.3s var(--transition-curve);
            box-shadow: var(--glow);
            display: flex;
            align-items: center;
            gap: 8px;
        }

