            font-size: 0.9rem;
            margin-top: 8px;
            display: none;
        }

        .success-message.show {
            display: block;
            animation: successSlide 0.3s ease;
        }

        @keyframes successSlide {
            from { opacity: 0; transform: translateY(-10px); }
            to { opacity: 1; transform: translateY(0); }
        }
    </style>
</head>
